<script setup>
import {ref,onBeforeUnmount,onMounted} from 'vue'
import {listAdminReviews,getAdminReview,replyReview,hideReview,restoreReview} from '../../api/review'
import {getRooms} from '../../api/room'
import {validAdminReview,validReviewPage,moderationIntent,validModerationReceipt} from '../../composables/reviewManagement.js'
import SInput from '../ui/SInput.vue'
import SButton from '../ui/SButton.vue'
import SSelect from '../ui/SSelect.vue'
import SDialog from '../ui/SDialog.vue'
import SBanner from '../ui/SBanner.vue'
import SEmpty from '../ui/SEmpty.vue'
const items=ref(null),page=ref(1),room=ref(''),hidden=ref(''),rooms=ref([]),roomsLoading=ref(false),roomsError=ref(''),loading=ref(false),listError=ref(''),selected=ref(null),detail=ref(null),detailLoading=ref(false),error=ref(''),draft=ref({reply:'',reason:''}),recheckReason=ref(''),dialog=ref(false),action=ref(null),pending=ref(null),submitting=ref(false),readPending=ref(false),receipt=ref(null),stale=ref(false)
async function loadRooms(){roomsLoading.value=true;roomsError.value='';try{const {data}=await getRooms();if(!alive)return;if(!Array.isArray(data))throw new Error('空间列表不完整');rooms.value=data}catch(e){if(alive)roomsError.value=e.message}finally{if(alive)roomsLoading.value=false}}
let alive=true,listTicket=0,detailTicket=0;const drafts=new Map(),copy=x=>JSON.parse(JSON.stringify(x))
onBeforeUnmount(()=>{alive=false;listTicket++;detailTicket++;drafts.clear()})
function locked(){return submitting.value||pending.value||readPending.value}
async function loadList(next=1){if(locked())return;if(!Number.isSafeInteger(next)||next<1){listError.value='页码须为正整数';return}const request={page:next,page_size:10};if(room.value){const id=Number(room.value);if(!Number.isSafeInteger(id)||id<1){listError.value='空间编号须为正整数';return}request.room_id=id}if(hidden.value!=='')request.hidden=hidden.value;const ticket=++listTicket;loading.value=true;listError.value='';try{const {data}=await listAdminReviews(request);if(!alive||ticket!==listTicket)return;if(!validReviewPage(data,request,validAdminReview))throw new Error('管理评价列表不完整');items.value=data;page.value=next}catch(e){if(alive&&ticket===listTicket)listError.value=e.message}finally{if(alive&&ticket===listTicket)loading.value=false}}
async function open(id,internal=false){if(locked()&&!internal)return;if(selected.value!==id){if(selected.value)drafts.set(selected.value,copy(draft.value));draft.value=copy(drafts.get(id)||{reply:'',reason:''});receipt.value=null;selected.value=id}const ticket=++detailTicket;detailLoading.value=true;error.value='';stale.value=false;if(!internal)detail.value=null;const recovering=readPending.value;try{const {data}=await getAdminReview(id);if(!alive||ticket!==detailTicket)return;if(!validAdminReview(data)||data.id!==id||readPending.value&&data.version<receipt.value.review.version)throw new Error('管理评价详情不完整');detail.value=data;readPending.value=false;if(recovering)await loadList(page.value)}catch(e){if(alive&&ticket===detailTicket)error.value=(readPending.value?'操作已保存，仅重试读取最新详情：':'')+e.message}finally{if(alive&&ticket===detailTicket)detailLoading.value=false}}
function prepare(kind){if(locked()||detailLoading.value||stale.value||!detail.value)return;try{moderationIntent(kind,kind==='reply'?draft.value.reply:draft.value.reason,detail.value.version);action.value=kind;dialog.value=true;error.value=''}catch(e){error.value=e.message}}
function close(){if(!locked())dialog.value=false}
async function confirm(){if(submitting.value||detailLoading.value||readPending.value||stale.value)return;if(!pending.value){if(!dialog.value||!detail.value)return;try{pending.value={id:detail.value.id,action:action.value,original:copy(detail.value),body:{...moderationIntent(action.value,action.value==='reply'?draft.value.reply:draft.value.reason,detail.value.version),operation_id:crypto.randomUUID()}}}catch(e){error.value=e.message;return}}const frozen=pending.value,ticket=detailTicket;submitting.value=true;error.value='';try{const {data}=await (frozen.action==='reply'?replyReview:hideReview)(frozen.id,frozen.body);if(!alive||ticket!==detailTicket)return;if(!validModerationReceipt(data,frozen))throw new Error('回执不完整，请保留原请求核对');receipt.value=data;pending.value=null;dialog.value=false;readPending.value=true;drafts.delete(frozen.id);draft.value={reply:'',reason:''}}catch(e){if(!alive||ticket!==detailTicket)return;error.value=e.message;if(e.status>=400&&e.status<500){pending.value=null;dialog.value=false;stale.value=true}}finally{if(alive&&ticket===detailTicket)submitting.value=false}if(alive&&ticket===detailTicket&&readPending.value)await open(frozen.id,true)}
async function recheck(action){
  if(locked()||detailLoading.value||stale.value||!detail.value)return
  const reason=recheckReason.value.trim()
  if(action==='hide'&&!reason){error.value='继续隐藏须填写1至1000字的公开理由';return}
  if(reason.length>1000){error.value='复核理由不能超过1000字';return}
  const body={operation_id:crypto.randomUUID(),version:detail.value.version,...(reason?{reason}:{})}
  submitting.value=true;error.value='';receipt.value=null
  try{
    const {data}=await (action==='restore'?restoreReview:hideReview)(detail.value.id,body)
    receipt.value=data;readPending.value=true;recheckReason.value=''
    await open(detail.value.id,true)
  }catch(e){if(alive)error.value=e.message}
  finally{if(alive)submitting.value=false}
}
onMounted(()=>{void loadRooms();void loadList()})
defineExpose({loadList})
</script>
<template><section class="review-management"><section class="card"><div class="card-title-row"><h3>评价管理</h3><SButton size="sm" :loading="loading" @click="loadList(items?.page||1)">刷新</SButton></div><form class="review-filter-row" @submit.prevent="loadList(1)"><label>空间<SSelect v-model="room" :options="[{value:'',label:'全部空间'},...rooms.map(r=>({value:r.id,label:r.name}))]" :disabled="loading||roomsLoading||!!pending||readPending"/></label><label>公开状态<SSelect v-model="hidden" :options="[{value:'',label:'全部'},{value:'false',label:'公开'},{value:'true',label:'已隐藏'}]" :disabled="loading||!!pending||readPending"/></label><SButton type="submit" :disabled="loading||!!pending||readPending">应用筛选</SButton></form><SBanner v-if="roomsError" type="error" :title="roomsError"/><SBanner v-if="listError" type="error" :title="listError"/><p v-if="loading" role="status">正在读取…</p><div class="record-box"><ul v-if="items"><li v-for="item in items.items" :key="item.id">评价#{{item.id}} · {{item.rating}}星 · {{item.room_name}} · {{item.hidden?'已隐藏':'公开'}}<SButton :disabled="!!pending||readPending||submitting" @click="open(item.id)">查看评价详情</SButton></li></ul><SEmpty v-if="items&&!items.items.length&&!listError&&!loading" description="该次查询无评价"/><p v-else-if="!items&&!loading&&!listError">尚未读取评价。</p></div><div v-if="items" class="list-footer"><span>共 {{ items.total }} 条</span><span class="page-info">第 {{ items.page }} / {{ Math.max(1, Math.ceil(items.total / items.page_size)) }} 页</span><div class="actions"><SButton :disabled="loading||items.page<=1||!!pending||readPending" @click="loadList(items.page-1)">上一页</SButton><SButton :disabled="loading||items.page*items.page_size>=items.total||!!pending||readPending" @click="loadList(items.page+1)">下一页</SButton></div></div></section>
<section v-if="selected" class="card"><h3>管理评价详情#{{selected}}</h3><SButton :disabled="detailLoading||submitting||!!pending" @click="open(selected,readPending)">刷新当前详情</SButton><SBanner v-if="error" type="error" :title="error"/><p v-if="detailLoading">正在读取…</p><p v-if="receipt">本次{{receipt.review.hidden?'隐藏/回复':'回复'}}操作已保存，版本{{receipt.review.version}}；下方为当前详情。</p><template v-if="detail&&!detailLoading"><p>{{detail.room_name}} · 本人预约#{{detail.reservation_id}} · {{detail.rating}}星（管理员不可改评分或原文）</p><p>评价人：{{detail.subject.real_name||detail.subject.username}} / {{detail.subject.username}} / {{detail.subject.campus_id||'校园编号未登记'}}</p><p class="content">{{detail.content}}</p><p>版本{{detail.version}} · {{detail.updated_at}} · {{detail.hidden?'已隐藏':'公开'}}</p><p v-if="detail.hidden" class="content">隐藏理由：{{detail.hidden_reason}}（{{detail.hidden_at}}）</p><section v-if="detail.recheck_pending||detail.recheck_required" class="recheck-panel"><h4>修改后待管理员复核</h4><p>本人修改隐藏评价后仍保持隐藏；请复核后恢复公开，或说明理由继续隐藏。</p><p v-if="detail.recheck_requested_at" class="muted">本人修改：{{detail.recheck_requested_at}}</p><label>复核说明<SInput v-model="recheckReason" type="textarea" maxlength="1000" :disabled="!!pending||readPending||submitting"/></label><div class="actions"><SButton variant="primary" :disabled="!!pending||readPending||submitting" @click="recheck('restore')">恢复公开</SButton><SButton :disabled="!!pending||readPending||submitting" @click="recheck('hide')">继续隐藏</SButton></div></section><p v-if="detail.admin_reply" class="content">管理回复：{{detail.admin_reply}}（{{detail.replied_at}}）</p><label>管理回复<SInput v-model="draft.reply" type="textarea" maxlength="2000" :disabled="!!pending||readPending||submitting"/></label><SButton :disabled="!!pending||readPending||submitting||stale" @click="prepare('reply')">核对管理回复</SButton><label>隐藏理由<SInput v-model="draft.reason" type="textarea" maxlength="1000" :disabled="!!pending||readPending||submitting||detail.hidden"/></label><SButton :disabled="!!pending||readPending||submitting||stale||detail.hidden" @click="prepare('hide')">核对隐藏评价</SButton><p v-if="stale">版本或条件变化，请刷新当前详情后重试；原草稿保留。</p></template></section>
<SDialog :model-value="dialog" @update:model-value="close" :title="action==='reply'?'确认管理回复':'确认隐藏评价'" :show-close="!submitting&&!pending" :close-on-click-modal="!submitting&&!pending" :close-on-escape="!submitting&&!pending"><p>评价#{{pending?.id||selected}} · {{pending?.original.rating||detail?.rating}}星；原评分和文字保持。</p><p class="content">{{pending?(pending.action==='reply'?pending.body.reply:pending.body.reason):action==='reply'?draft.reply:draft.reason}}</p><p v-if="action==='hide'">隐藏后校园公开列表不再显示，本人仍可查看原文、理由并修改自身评价；修改不恢复公开。</p><p v-if="pending">操作结果尚需核对，保留原请求和标识主动重试。</p><SBanner v-if="error" type="error" :title="error"/><template #footer><SButton v-if="!pending" :disabled="submitting" @click="close">返回草稿</SButton><SButton variant="primary" :disabled="submitting" @click="confirm">{{pending?'按原请求核对':'确认操作'}}</SButton></template></SDialog></section></template>
<style scoped>.list-footer{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:12px;margin-top:12px;color:var(--text-3);font-size:var(--fs-caption)}.page-info{text-align:center;white-space:nowrap}.list-footer .actions{justify-content:flex-end;justify-self:end}
.review-filter-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;gap:12px;align-items:end}.review-filter-row label{display:grid;gap:7px}.record-box{border:1px solid var(--border);border-radius:var(--r-lg);padding:16px;display:grid;gap:12px;min-height:120px;min-width:0}.review-management,.review-management .card,.review-management form,.review-management label{display:grid;gap:12px;min-width:0;overflow-wrap:anywhere}.review-management li{margin-bottom:12px}.content{white-space:pre-wrap;overflow-wrap:anywhere}.actions{display:flex;gap:12px;flex-wrap:wrap}.recheck-panel{display:grid;gap:10px;padding:14px 16px;border:1px solid var(--amber-weak);border-radius:var(--r-md);background:var(--amber-faint)}.recheck-panel h4{font-family:var(--font-display);color:var(--text-1);font-size:16px}.recheck-panel p{color:var(--text-2);font-size:var(--fs-body-sm)}</style>
